"""HTTP API for datasets, immutable schema versions and field lineage."""

from __future__ import annotations

import sqlite3

from fastapi import Depends, FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse

from app import repository
from app.db import get_db
from app.errors import APIError
from app.models import (
    Dataset,
    DatasetCreate,
    FieldSpec,
    LineageCreate,
    LineageCreatedResponse,
    LineageResponse,
    SchemaVersion,
    SchemaVersionCreate,
)

app = FastAPI(title="Data Lineage Trust Platform", version="0.1.0")


@app.exception_handler(APIError)
def handle_api_error(request: Request, exc: APIError) -> JSONResponse:
    return JSONResponse(
        status_code=exc.status_code,
        content={"error": exc.code, "detail": exc.message},
    )


def _sanitize_validation_message(message: str) -> str:
    # Pydantic messages can embed raw input; keep responses free of internals.
    if message.startswith("Field required"):
        return "Request body is incomplete: a required field is missing"
    if "JSON decode" in message:
        return "Request body is not valid JSON"
    return "The request payload is invalid"


@app.exception_handler(RequestValidationError)
def handle_validation_error(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    missing: list[str] = []
    invalid: list[str] = []
    for error in exc.errors():
        loc = [str(part) for part in error.get("loc", ()) if part != "body"]
        path = ".".join(loc)
        if error.get("type") == "missing":
            missing.append(path or "body")
        else:
            invalid.append(path or "body")
    if missing:
        message = (
            "Request body is incomplete: missing field(s) "
            + ", ".join(sorted(set(missing)))
        )
    elif invalid:
        malformed = ", ".join(sorted(set(invalid)))
        message = f"The request payload is invalid for field(s) {malformed}"
    else:
        message = "The request payload is invalid"
    return JSONResponse(
        status_code=422,
        content={"error": "validation_error", "detail": msg_or_fallback(exc, message)},
    )


def msg_or_fallback(exc: RequestValidationError, fallback: str) -> str:
    # Pydantic v2 exposes the first message; some (e.g. invalid JSON) are
    # generic enough to surface, but we never echo SQL or stack information.
    return fallback


@app.exception_handler(sqlite3.Error)
def handle_sqlite_error(request: Request, exc: sqlite3.Error) -> JSONResponse:
    return JSONResponse(
        status_code=500,
        content={"error": "internal_error", "detail": "An internal error occurred"},
